SELECT e.*, sl.layer_name AS layer_name, sl.shelf_code AS shelf_code
FROM layer_capacity_expand_record e
LEFT JOIN shelf_layer sl ON e.layer_code = sl.layer_code


        AND e.status = #{query.status}


        AND e.layer_code LIKE CONCAT('%', #{query.layerCode}, '%')


        AND e.start_time >= #{query.startTime}


        AND e.start_time <= #{query.endTime}


ORDER BY e.start_time DESC, e.id DESC

SELECT e.*, sl.layer_name AS layer_name, sl.shelf_code AS shelf_code
FROM layer_capacity_expand_record e
LEFT JOIN shelf_layer sl ON e.layer_code = sl.layer_code
WHERE e.layer_code = #{layerCode}
  AND e.status IN ('PENDING', 'ACTIVE')
  AND e.start_time <= #{now}
  AND e.end_time >= #{now}
ORDER BY e.start_time DESC, e.id DESC
LIMIT 1

mapper.update:
UPDATE layer_capacity_expand_record
SET status = 'ACTIVE', update_time = #{now}
WHERE status = 'PENDING' AND start_time <= #{now} AND end_time >= #{now}
